const body = $json.body ?? $json;
const periodStart = String(body.periodStart ?? '').trim();
const periodEnd = String(body.periodEnd ?? '').trim();
const totalBudget = Number(body.totalBudget ?? body.availableBudget ?? 0);
const minimumSpend = Number(body.minimumSpend ?? 0);
const maximumSpend = Number(body.maximumSpend ?? 0);
if (!periodStart || !periodEnd) throw new Error('periodStart and periodEnd are required');
if (new Date(periodStart).getTime() > new Date(periodEnd).getTime()) throw new Error('periodStart must be before periodEnd');
if (!Number.isFinite(totalBudget) || totalBudget < 0) throw new Error('totalBudget must be a non-negative number');
return [{ json: { periodStart, periodEnd, totalBudget, minimumSpend: Math.max(0, minimumSpend), maximumSpend: Math.max(0, maximumSpend), requestedAt: new Date().toISOString() } }];

const ctx = $json.data ?? $json;
const sources = Array.isArray(ctx.sources) ? ctx.sources : (Array.isArray(ctx.records) ? ctx.records : []);
const valid = sources.filter(s => s && (s.source || s.leadSource || s.marketingChannel || s.channel || s.campaign));
if (!valid.length) throw new Error('No valid lead-generation source performance data available for the requested period');
return [{ json: { sources: valid, periodStart: $('Normalize Budget Allocation Request').first().json.periodStart, periodEnd: $('Normalize Budget Allocation Request').first().json.periodEnd, totalBudget: $('Normalize Budget Allocation Request').first().json.totalBudget, minimumSpend: $('Normalize Budget Allocation Request').first().json.minimumSpend, maximumSpend: $('Normalize Budget Allocation Request').first().json.maximumSpend } }];

const sources = $json.sources;
const totalBudget = Number($json.totalBudget);
const minSpend = Number($json.minimumSpend);
const maxSpend = Number($json.maximumSpend);
const num = v => Number.isFinite(Number(v)) ? Number(v) : 0;
const rows = sources.map(s => {
  const leads = num(s.leads ?? s.leadCount);
  const qualifiedLeads = num(s.qualifiedLeads ?? s.qualifiedLeadCount);
  const contracts = num(s.contracts ?? s.contractCount);
  const closedDeals = num(s.closedDeals ?? s.closedDealCount);
  const netProfit = num(s.netProfit);
  const spend = num(s.spend ?? s.sourceSpend ?? s.campaignSpend);
  const roi = spend ? (netProfit - spend) / spend : null;
  const leadToCloseRate = leads ? closedDeals / leads : 0;
  const profitPerLead = leads ? netProfit / leads : 0;
  const profitPerDollar = spend ? netProfit / spend : 0;
  const score = (roi === null ? 0 : Math.max(0, Math.min(4, roi + 1))) * 0.35 + Math.min(1, leadToCloseRate * 10) * 0.25 + Math.min(1, profitPerLead / 1000) * 0.20 + Math.min(1, profitPerDollar / 4) * 0.20;
  return { source: String(s.source ?? s.leadSource ?? 'unknown'), marketingChannel: String(s.marketingChannel ?? s.channel ?? 'unknown'), campaign: String(s.campaign ?? s.campaignName ?? 'unknown'), leads, qualifiedLeads, contracts, closedDeals, netProfit, spend, roi, leadToCloseRate, profitPerLead, profitPerDollar, score };
}).sort((a,b) => b.score - a.score);
const positive = rows.filter(r => r.score > 0);
const scoreTotal = positive.reduce((sum,r) => sum + r.score, 0);
let remaining = totalBudget;
const allocations = rows.map((r, i) => {
  let allocation = scoreTotal ? totalBudget * (r.score / scoreTotal) : (rows.length ? totalBudget / rows.length : 0);
  if (minSpend > 0 && r.score > 0) allocation = Math.max(allocation, minSpend);
  if (maxSpend > 0) allocation = Math.min(allocation, maxSpend);
  allocation = Math.max(0, allocation);
  remaining -= allocation;
  return { ...r, recommendedBudget: Number(allocation.toFixed(2)), action: r.roi === null ? 'test_with_tracking' : r.roi >= 1 ? 'scale' : r.roi >= 0 ? 'maintain_and_optimize' : 'reduce_or_pause' };
});
if (remaining < -0.01 && allocations.length) {
  const factor = totalBudget / allocations.reduce((s,r) => s + r.recommendedBudget, 0);
  for (const r of allocations) r.recommendedBudget = Number((r.recommendedBudget * factor).toFixed(2));
}
const allocatedBudget = allocations.reduce((s,r) => s + r.recommendedBudget, 0);
const unallocatedBudget = Number(Math.max(0, totalBudget - allocatedBudget).toFixed(2));
return [{ json: { periodStart: $json.periodStart, periodEnd: $json.periodEnd, totalBudget, allocations, allocatedBudget: Number(allocatedBudget.toFixed(2)), unallocatedBudget, allocationMethod: 'performance_weighted_source_scaling', generatedAt: new Date().toISOString() } }];
